CREATE TABLE "import_failures" ("id" TEXT NOT NULL, "redacted_snippet" TEXT NOT NULL, "reason" TEXT NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "node_groups" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sort_index" INTEGER NOT NULL DEFAULT 0, "is_collapsed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_collapsed" IN (0, 1)), "created_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "nodes" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "protocol" TEXT NOT NULL, "host" TEXT NOT NULL, "port" INTEGER NOT NULL, "subscription_id" TEXT NULL REFERENCES subscriptions (id) ON DELETE CASCADE, "group_id" TEXT NULL REFERENCES node_groups (id) ON DELETE CASCADE, "country_code" TEXT NULL, "latency_micros" INTEGER NULL, "last_checked_at" TEXT NULL, "sort_index" INTEGER NOT NULL DEFAULT 0, "public_params_json" TEXT NOT NULL DEFAULT '{}', "secret_ref" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "routing_rules" ("id" TEXT NOT NULL, "matcher" TEXT NOT NULL, "action" TEXT NOT NULL, "sort_index" INTEGER NOT NULL DEFAULT 0, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value_json" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "subscriptions" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "url_ref" TEXT NOT NULL, "redacted_url" TEXT NOT NULL, "user_info_json" TEXT NULL, "profile_title" TEXT NULL, "announcement" TEXT NULL, "profile_web_page_url" TEXT NULL, "support_url" TEXT NULL, "update_interval_hours" INTEGER NULL, "user_agent_override" TEXT NULL, "auto_update" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_update" IN (0, 1)), "last_updated_at" TEXT NULL, "sort_index" INTEGER NOT NULL DEFAULT 0, "is_collapsed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_collapsed" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "traffic_daily" ("day" TEXT NOT NULL, "scope" TEXT NOT NULL DEFAULT '', "up_bytes" INTEGER NOT NULL DEFAULT 0, "down_bytes" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("day", "scope"));
